describe('Kalshi parser', () => {
  const combo = {
    events: [
      {
        event_ticker: 'KXBALANCEPOWERCOMBO-27FEB',
        markets: [
          { ticker: 'KXBALANCEPOWERCOMBO-27FEB-DD', yes_sub_title: 'Democrats sweep', yes_bid_dollars: '0.6200', yes_ask_dollars: '0.6300', last_price_dollars: '0.6300' },
          { ticker: 'KXBALANCEPOWERCOMBO-27FEB-RR', yes_sub_title: 'Republicans sweep', yes_bid_dollars: '0.0780', yes_ask_dollars: '0.0790' },
          { ticker: 'KXBALANCEPOWERCOMBO-27FEB-RD', yes_sub_title: 'R-House, D-Senate', yes_bid_dollars: '0', yes_ask_dollars: '1', last_price_dollars: '0.0130' },
        ],
      },
    ],
  };

  it('uses the bid/ask midpoint (62/63 ¢ → 62.5 %)', () => {
    const ms = parseKalshiEvent(combo, 'KXBALANCEPOWERCOMBO-27FEB');
    expect(findByTickerSuffix(ms, '-DD')?.p).toBe(0.625);
    expect(Math.abs(findByTickerSuffix(ms, '-DD')!.p - RESEARCH.kalshi.sweep)).toBeLessThan(0.01);
  });

  it('falls back to last trade on an empty book', () => {
    expect(findByTickerSuffix(parseKalshiEvent(combo, 'KXBALANCEPOWERCOMBO-27FEB'), '-RD')?.p).toBe(0.013);
    expect(midpoint(0, 1)).toBeNull();
  });

  it('throws for a missing event', () => {
    expect(() => parseKalshiEvent(combo, 'NOPE')).toThrow(/not found/);
  });

  it('parses candlesticks, using bid/ask mid on days without trades', () => {
    const pts = parseKalshiCandles({
      candlesticks: [
        { end_period_ts: 100, price: { close_dollars: '0.5800' } },
        { end_period_ts: 200, price: {}, yes_bid: { close_dollars: '0.6100' }, yes_ask: { close_dollars: '0.6300' } },
        { end_period_ts: 300, price: {} },
      ],
    });
    expect(pts).toEqual([
      { t: 100, p: 0.58 },
      { t: 200, p: 0.62 },
    ]);
  });
});

describe('DDHQ parser', () => {
  const overviews = [
    {
      toplineId: 2,
      officeId: 3,
      forecast: {
        parties: [
          { partyId: 2, abbrev: 'GOP', winProbability: 0.25, seats: 201 },
          { partyId: 1, abbrev: 'DEM', winProbability: RESEARCH.ddhq.house, seats: 234 },
        ],
        updatedAt: '2026-10-02 14:02:43.692836',
      },
      timeseries: [{ date: '2026-05-28', parties: [{ abbrev: 'DEM', winProbability: 0.7, seats: 234 }] }],
    },
    {
      toplineId: 3,
      officeId: 4,
      forecast: {
        parties: [
          { partyId: 2, abbrev: 'GOP', winProbability: 0.46, seats: 49 },
          { partyId: 1, abbrev: 'DEM', winProbability: RESEARCH.ddhq.senate, seats: 51 },
        ],
        updatedAt: '2026-10-02 14:06:54.237766',
      },
      timeseries: [
        { date: '2026-06-19', parties: [{ abbrev: 'DEM', winProbability: 0.46, seats: 50 }] },
        { date: '2026-10-02', parties: [{ abbrev: 'DEM', winProbability: 0.54, seats: 51 }] },
      ],
    },
  ];
  // RSC payload is embedded as an escaped JS string inside a script tag.
  const rsc = JSON.stringify(`["$","$L3d",null,{"overviews":${JSON.stringify(overviews)}}]`).slice(1, -1);
  const html = `<html><body>
    <h3 class="text-sm font-semibold">DEM Senate and DEM House</h3><span class="text-lg font-bold">52.0<!-- -->%</span>
    <h3 class="text-sm font-semibold">DEM Senate and GOP House</h3><span class="text-lg font-bold">2.0<!-- -->%</span>
    <script>self.__next_f.push([1,"${rsc}"])</script></body></html>`;

  it('extracts House 75 %, Senate 54 %, Sweep 52 %', () => {
    const f = parseDdhq(html);
    expect(f.house).toBe(RESEARCH.ddhq.house);
    expect(f.senate).toBe(RESEARCH.ddhq.senate);
    expect(f.sweep).toBe(RESEARCH.ddhq.sweep);
    expect(f.updatedAt).toBe('2026-10-02 14:06:54.237766');
  });

  it('identifies chambers by seat totals, not order', () => {
    const swapped = html.replace(JSON.stringify(overviews).replace(/"/g, '\\"'), JSON.stringify([...overviews].reverse()).replace(/"/g, '\\"'));
    expect(parseDdhq(swapped).house).toBe(0.75);
  });

  it('maps timeseries to points', () => {
    const f = parseDdhq(html);
    expect(f.senateHistory.map((p) => p.p)).toEqual([0.46, 0.54]);
    expect(f.houseHistory).toHaveLength(1);
  });

  it('returns sweep null when the combo block is missing, and throws without overviews', () => {
    expect(parseDdhq(html.replace(/DEM Senate and DEM House/, 'changed')).sweep).toBeNull();
    expect(() => parseDdhq('<html></html>')).toThrow();
  });

  it('extractJsonArray handles brackets inside strings', () => {
    expect(extractJsonArray('x"k":[{"a":"]["},1] tail', 'k')).toEqual([{ a: '][' }, 1]);
  });
});

